function validate(input) {
  const [{ Student = [], Exam = [] }] = input;
  const students = new Set();
  for (const [id] of Student) {
    if (id === null) return 'Every student needs a student_id.';
    if (students.has(id)) return `student_id ${id} appears twice in Student.`;
    students.add(id);
  }
  const seen = new Set();
  for (const [exam, student, score] of Exam) {
    if (exam === null || student === null) return 'Every exam row needs an exam_id and a student_id.';
    if (score === null) return 'score is never null.';
    if (!students.has(student)) return `Exam names student ${student}, who is not in Student.`;
    const key = `${exam}/${student}`;
    if (seen.has(key)) return `Student ${student} sat exam ${exam} twice.`;
    seen.add(key);
  }
  return null;
}

