function generate(rand, size) {
  const small = size === 'small';
  const names = ['Daniel', 'Jade', 'Stella', 'Jonathan', 'Will', 'Mia', 'Omar', 'Lena'];
  const studentCount = small ? Math.floor(rand() * 7) : 400;
  const examCount = small ? 1 + Math.floor(rand() * 3) : 25;
  const ids = [];
  for (let i = 1; i <= studentCount; i++) ids.push(i * 2 + 1);
  // Shuffle so students are stored out of id order.
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Student = ids.map((id) => [id, names[Math.floor(rand() * names.length)]]);
  const pairs = [];
  for (let e = 1; e <= examCount; e++) for (const id of ids) if (rand() < (small ? 0.6 : 0.2)) pairs.push([e * 10, id]);
  const limit = small ? 8 : 2000;
  const scores = small ? [60, 70, 70, 80, 90] : null;
  const Exam = pairs.slice(0, limit).map(([e, id]) => [e, id, scores ? scores[Math.floor(rand() * scores.length)] : 40 + 5 * Math.floor(rand() * 13)]);
  return [{ Student, Exam }];
}
